//! `velt.lock`: the exact versions, sources and content hashes a package was resolved to.
//!
//! ```toml
//! # This file is generated by vpm. Do not edit.
//! version = 1
//!
//! [[package]]
//! name = "json"
//! version = "1.2.0"
//! source = "registry"
//! checksum = "sha256:…"
//! dependencies = ["util"]
//!
//! [[package]]
//! name = "util"
//! version = "0.1.0"
//! source = "path+../util"
//! ```
//! Path sources are relative to the root package, `/`-separated. The root package itself is not
//! listed (its dependencies come from velt.toml).

use std::path::Path;

use serde::{Deserialize, Serialize};

/// File name of the lockfile at the root package.
pub const LOCK_FILE: &str = "velt.lock";
const FORMAT_VERSION: u32 = 1;
const HEADER: &str = "# This file is generated by vpm. Do not edit.\n";

/// A whole lockfile.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Lockfile {
    /// Lockfile format version (currently 1).
    pub version: u32,
    /// Resolved packages, sorted by name.
    #[serde(default, rename = "package")]
    pub packages: Vec<LockedPackage>,
}

/// One resolved package.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct LockedPackage {
    /// Package name.
    pub name: String,
    /// Exact version.
    pub version: String,
    /// `"registry"` or `"path+<dir relative to the root package>"`.
    pub source: String,
    /// Content checksum (registry packages only).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub checksum: Option<String>,
    /// Names of this package's direct dependencies.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dependencies: Vec<String>,
}

/// The `source` value for registry packages.
pub const REGISTRY_SOURCE: &str = "registry";

impl Lockfile {
    /// A lockfile over `packages` (sorted by name for stable diffs).
    pub fn new(mut packages: Vec<LockedPackage>) -> Lockfile {
        packages.sort_by(|a, b| a.name.cmp(&b.name));
        Lockfile {
            version: FORMAT_VERSION,
            packages,
        }
    }

    /// Parse lockfile text.
    pub fn parse(text: &str) -> Result<Lockfile, String> {
        let lock: Lockfile =
            toml::from_str(text).map_err(|e| format!("invalid {LOCK_FILE}: {e}"))?;
        if lock.version != FORMAT_VERSION {
            return Err(format!(
                "unsupported {LOCK_FILE} format version {} (expected {FORMAT_VERSION})",
                lock.version
            ));
        }
        Ok(lock)
    }

    /// Read `<root>/velt.lock`; `Ok(None)` if there is none.
    pub fn read(root: &Path) -> Result<Option<Lockfile>, String> {
        let path = root.join(LOCK_FILE);
        if !path.is_file() {
            return Ok(None);
        }
        let text = std::fs::read_to_string(&path)
            .map_err(|e| format!("cannot read `{}`: {e}", path.display()))?;
        Lockfile::parse(&text)
            .map(Some)
            .map_err(|e| format!("{}: {e}", path.display()))
    }

    /// Write `<root>/velt.lock`.
    pub fn write(&self, root: &Path) -> Result<(), String> {
        let path = root.join(LOCK_FILE);
        std::fs::write(&path, self.to_toml())
            .map_err(|e| format!("cannot write `{}`: {e}", path.display()))
    }

    /// Serialized text including the header comment.
    pub fn to_toml(&self) -> String {
        format!(
            "{HEADER}{}",
            toml::to_string(self).expect("ICE: lockfile serialization cannot fail")
        )
    }

    /// The locked entry for `name`, if any.
    pub fn get(&self, name: &str) -> Option<&LockedPackage> {
        self.packages.iter().find(|p| p.name == name)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let lock = Lockfile::new(vec![
            LockedPackage {
                name: "util".into(),
                version: "0.1.0".into(),
                source: "path+../util".into(),
                checksum: None,
                dependencies: vec![],
            },
            LockedPackage {
                name: "json".into(),
                version: "1.2.0".into(),
                source: REGISTRY_SOURCE.into(),
                checksum: Some("sha256:00".into()),
                dependencies: vec!["util".into()],
            },
        ]);
        assert_eq!(lock.packages[0].name, "json");
        let text = lock.to_toml();
        assert!(text.starts_with("# This file"));
        assert!(text.contains("[[package]]"));
        assert_eq!(Lockfile::parse(&text).unwrap(), lock);
        assert_eq!(lock.get("util").unwrap().version, "0.1.0");
    }

    #[test]
    fn rejects_unknown_format() {
        assert!(Lockfile::parse("version = 9\n")
            .unwrap_err()
            .contains("format version"));
    }
}
